package indexing

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"testing"

	"magworkspace/internal/domain"
)

type manifestMemory struct{ data []byte }

func (m *manifestMemory) Put(_ context.Context, _ string, b []byte) error {
	m.data = append([]byte(nil), b...)
	return nil
}

// These spans are frozen output from the original 800/100 splitter, not
// regenerated by whichever implementation happens to be current.
func TestManifestLegacyFrozenSpans(t *testing.T) {
	text := strings.Repeat("a", 730) + "\n\n" + strings.Repeat("b", 1000)
	job := manifestTestJob()
	m := manifest{Format: 1, IndexID: job.ID, Generation: job.Generation, DocumentID: job.DocumentID, VersionID: job.VersionID, SourceSHA256: job.SourceSHA256, Text: text}
	for i, span := range [][2]int{{0, 732}, {632, 1432}, {1332, 1732}} {
		m.Chunks = append(m.Chunks, manifestChunk{ID: fmt.Sprintf("%032x", i+1), Ordinal: i, StartByte: span[0], EndByte: span[1], SHA256: digestBytes([]byte(text[span[0]:span[1]]))})
	}
	data, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	job.ArtifactSHA256, job.ChunkCount = digestBytes(data), len(m.Chunks)
	s := &Service{objects: &manifestMemory{data: data}}
	chunks, err := s.loadManifest(context.Background(), job)
	if err != nil {
		t.Fatal(err)
	}
	for i, c := range chunks {
		want := m.Chunks[i]
		if c.StartByte != want.StartByte || c.EndByte != want.EndByte || c.ID != want.ID || c.SHA256 != want.SHA256 || c.Content != text[want.StartByte:want.EndByte] {
			t.Fatal("legacy immutable span changed")
		}
	}
	current, err := Split(text)
	if err != nil {
		t.Fatal(err)
	}
	if len(current) == len(chunks) {
		same := true
		for i := range current {
			same = same && current[i].StartByte == chunks[i].StartByte && current[i].EndByte == chunks[i].EndByte
		}
		if same {
			t.Fatal("fixture does not distinguish legacy and current strategies")
		}
	}
}

func manifestTestJob() domain.IndexJob {
	j := domain.IndexJob{ID: strings.Repeat("1", 32), ProfileID: strings.Repeat("a", 64), Generation: strings.Repeat("2", 32), DocumentID: strings.Repeat("3", 32), VersionID: strings.Repeat("4", 32), SourceSHA256: strings.Repeat("5", 64), Status: "ready"}
	j.ArtifactKey = artifactKey(j.ProfileID, j.Generation)
	return j
}

func TestManifestStrategyAndTamperedSpans(t *testing.T) {
	for _, strategy := range []string{ChunkingLegacy, ChunkingStructure} {
		t.Run(strategy, func(t *testing.T) {
			job := manifestTestJob()
			text := strings.Repeat("这是可以定位的中文句子。", 150)
			chunks, err := SplitWithStrategy(text, strategy)
			if err != nil {
				t.Fatal(err)
			}
			for i := range chunks {
				chunks[i].ID = fmt.Sprintf("%032x", i+1)
			}
			data, err := encodeManifest(job, text, chunks, strategy)
			if err != nil {
				t.Fatal(err)
			}
			var original manifest
			if err = json.Unmarshal(data, &original); err != nil {
				t.Fatal(err)
			}
			if strategy == ChunkingLegacy && (original.Format != 1 || original.ChunkingStrategy != "") || strategy == ChunkingStructure && (original.Format != 2 || original.ChunkingStrategy != strategy) {
				t.Fatal("incorrect format/strategy binding")
			}
			job.ArtifactSHA256, job.ChunkCount = digestBytes(data), len(chunks)
			memory := &manifestMemory{data: data}
			s := &Service{objects: memory}
			got, err := s.loadManifest(context.Background(), job)
			if err != nil || len(got) != len(chunks) {
				t.Fatal("round trip failed", err)
			}
			for i := range chunks {
				chunks[i].IndexID, chunks[i].DocumentID, chunks[i].VersionID, chunks[i].SourceSHA256 = job.ID, job.DocumentID, job.VersionID, job.SourceSHA256
			}
			if !reflect.DeepEqual(got, chunks) {
				t.Fatal("round trip changed chunk identity")
			}
			for name, mutate := range map[string]func(*manifest){
				"unknown format":      func(m *manifest) { m.Format = 3 },
				"unknown strategy":    func(m *manifest) { m.ChunkingStrategy = "future" },
				"missing v2 strategy": func(m *manifest) { m.Format, m.ChunkingStrategy = 2, "" },
				"v2 with legacy":      func(m *manifest) { m.Format, m.ChunkingStrategy = 2, ChunkingLegacy },
				"v1 with v2":          func(m *manifest) { m.Format, m.ChunkingStrategy = 1, ChunkingStructure },
				"changed span":        func(m *manifest) { m.Chunks[0].EndByte-- },
				"changed hash":        func(m *manifest) { m.Chunks[0].SHA256 = strings.Repeat("0", 64) },
				"changed ordinal":     func(m *manifest) { m.Chunks[0].Ordinal = 1 },
				"duplicate id":        func(m *manifest) { m.Chunks[1].ID = m.Chunks[0].ID },
				"invalid id":          func(m *manifest) { m.Chunks[0].ID = strings.Repeat("g", 32) },
				"changed text":        func(m *manifest) { m.Text = "修改" + m.Text },
			} {
				t.Run(name, func(t *testing.T) {
					var m manifest
					if err := json.Unmarshal(data, &m); err != nil {
						t.Fatal(err)
					}
					mutate(&m)
					changed, err := json.Marshal(m)
					if err != nil {
						t.Fatal(err)
					}
					memory.data = changed
					job.ArtifactSHA256 = digestBytes(changed)
					if _, err = s.loadManifest(context.Background(), job); ErrorCode(err) != "artifact_integrity_failed" {
						t.Fatalf("accepted tampered manifest: %v", err)
					}
				})
			}
		})
	}
}
func (m *manifestMemory) Read(context.Context, string, int) ([]byte, error) { return m.data, nil }
func (m *manifestMemory) Delete(context.Context, string) error              { return nil }

func TestManifestCanonicalTextAndIntegrity(t *testing.T) {
	job := domain.IndexJob{ID: strings.Repeat("1", 32), ProfileID: strings.Repeat("a", 64), Generation: strings.Repeat("2", 32), DocumentID: strings.Repeat("3", 32), VersionID: strings.Repeat("4", 32), SourceSHA256: strings.Repeat("5", 64), Status: "ready"}
	text := strings.Repeat("中文知识库不可变文档。", 150)
	chunks, err := Split(text)
	if err != nil {
		t.Fatal(err)
	}
	for i := range chunks {
		chunks[i].ID = strings.Repeat(string(rune('a'+i)), 32)
	}
	data, err := encodeManifest(job, text, chunks, ChunkingStructure)
	if err != nil {
		t.Fatal(err)
	}
	job.ArtifactKey = artifactKey(job.ProfileID, job.Generation)
	job.ArtifactSHA256 = digestBytes(data)
	job.ChunkCount = len(chunks)
	memory := &manifestMemory{data: data}
	s := &Service{objects: memory}
	got, err := s.loadManifest(context.Background(), job)
	if err != nil {
		t.Fatal(err)
	}
	for i, c := range got {
		if c.Content != chunks[i].Content || c.ID != chunks[i].ID || c.VersionID != job.VersionID || c.IndexID != job.ID {
			t.Fatalf("wrong canonical chunk %+v", c)
		}
	}
	memory.data = append([]byte(nil), data...)
	memory.data[len(data)/2] ^= 1
	if _, err = s.loadManifest(context.Background(), job); err == nil {
		t.Fatal("corruption was accepted")
	}
	memory.data = data
	job.VersionID = strings.Repeat("9", 32)
	if _, err = s.loadManifest(context.Background(), job); err == nil {
		t.Fatal("wrong version binding was accepted")
	}
}
